<?php require __DIR__.'/../src/bootstrap.php';require_login();$type=$_GET['type']??'';$id=(int)($_GET['id']??0);$allowed=['banners','categories','channels','matches','movies','series','notifications'];if(!in_array($type,$allowed,true))exit('Invalid');if(($_GET['a']??'')==='delete')delete_item($type,$id);if(($_GET['a']??'')==='toggle'){$all=db_read($type);foreach($all as &$x)if((int)($x['id']??0)===$id)$x['enabled']=!($x['enabled']??true);db_write($type,$all);}header('Location:content.php?type='.$type);